begin;
create function public.fixture_assert(ok boolean,label text) returns void language plpgsql as $$begin if ok is distinct from true then raise exception 'SQL_CONTRACT_FAILED: %',label;end if;end$$;
insert into auth.users select ('00000000-0000-4000-8000-'||lpad(n::text,12,'0'))::uuid from generate_series(1,8)n;
insert into auth.sessions select ('10000000-0000-4000-8000-'||lpad(n::text,12,'0'))::uuid,('00000000-0000-4000-8000-'||lpad(n::text,12,'0'))::uuid,case when n=8 then now()-interval '1 hour' else now()+interval '1 day' end from generate_series(1,8)n;
insert into scenario_private.projects(id,owner_id,collaboration) values('20000000-0000-4000-8000-000000000001','00000000-0000-4000-8000-000000000001',true),('20000000-0000-4000-8000-000000000002','00000000-0000-4000-8000-000000000005',true);
insert into scenario_private.memberships(project_id,account_id,role,expires_at,revoked_at) select '20000000-0000-4000-8000-000000000001',('00000000-0000-4000-8000-'||lpad(n::text,12,'0'))::uuid,case n when 1 then 'owner' when 2 then 'editor' when 3 then 'reviewer' else 'reader' end,case when n=6 then now()-interval '1 hour' end,case when n=7 then now() end from generate_series(1,8)n where n<>5;
insert into scenario_private.documents(project_id,id,revision,document) select '20000000-0000-4000-8000-000000000001',('30000000-0000-4000-8000-'||lpad(n::text,12,'0'))::uuid,0,jsonb_build_object('fields',jsonb_build_object('visibility',case n when 1 then 'private' else 'team' end,'name',case n when 1 then 'SECRET_CANARY' else 'TEAM' end)) from generate_series(1,2)n;
insert into public.scenario_snapshots(id,public_project_id,projection,content_hash) values('40000000-0000-4000-8000-000000000001','public-story','{"entities":[{"id":"public-note","kind":"note","data":{"body":[{"id":"public-block","text":"😀公開"}]}}],"relations":[{"id":"public-line"}]}',repeat('a',64));
insert into scenario_private.snapshot_bindings values('40000000-0000-4000-8000-000000000001','20000000-0000-4000-8000-000000000001','50000000-0000-4000-8000-000000000001',repeat('b',64));
insert into scenario_private.snapshot_grants(snapshot_id,account_id) select '40000000-0000-4000-8000-000000000001',('00000000-0000-4000-8000-'||lpad(n::text,12,'0'))::uuid from generate_series(2,8)n;
insert into scenario_private.assets values('20000000-0000-4000-8000-000000000001',repeat('a',64),4,'text/plain','private','20000000-0000-4000-8000-000000000001/aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa',true),('20000000-0000-4000-8000-000000000001',repeat('b',64),4,'text/plain','team','20000000-0000-4000-8000-000000000001/bbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbb',true);
insert into storage.objects(bucket_id,name) select 'scenario-private',storage_path from scenario_private.assets;

set local role authenticated;
select set_config('request.jwt.claims','{"sub":"00000000-0000-4000-8000-000000000003","session_id":"10000000-0000-4000-8000-000000000003"}',true);
insert into public.scenario_comments(id,snapshot_id,public_entity_id,public_block_id,start_cp,end_cp,body)values('60000000-0000-4000-8000-000000000001','40000000-0000-4000-8000-000000000001','public-note','public-block',0,2,'元の引用への指摘');
select public.fixture_assert((select review_stage='open'and not resolved from public.scenario_comments),'review initially open');
do $$begin begin update public.scenario_comments set review_stage='verified';raise exception 'unexpected stage skip';exception when raise_exception then if sqlerrm<>'REVIEW_STAGE_ORDER'then raise;end if;end;end$$;
select set_config('request.jwt.claims','{"sub":"00000000-0000-4000-8000-000000000001","session_id":"10000000-0000-4000-8000-000000000001"}',true);
update public.scenario_comments set review_stage='fixed';select public.fixture_assert((select review_stage='fixed'and resolved from public.scenario_comments),'author marks reviewer comment fixed');
do $$begin begin update public.scenario_comments set body='作者が他人の指摘を改変';raise exception 'unexpected author body change';exception when insufficient_privilege then null;end;end$$;
update public.scenario_comments set review_stage='verified';select public.fixture_assert((select review_stage='verified'and resolved and body='元の引用への指摘'and public_block_id='public-block'and start_cp=0 and end_cp=2 from public.scenario_comments),'author verifies with immutable source');
update public.scenario_comments set review_stage='open';select public.fixture_assert((select review_stage='open'and not resolved from public.scenario_comments),'explicit reopen');
do $$begin begin update public.scenario_comments set end_cp=3;raise exception 'unexpected target change';exception when raise_exception then if sqlerrm<>'TARGET_IMMUTABLE'then raise;end if;end;end$$;
do $$begin begin perform *from scenario_private.review_sources;raise exception 'unexpected private source read';exception when insufficient_privilege then null;end;end$$;
do $$begin begin perform public.scenario_review_source('00000000-0000-4000-8000-000000000001','10000000-0000-4000-8000-000000000001','20000000-0000-4000-8000-000000000001','40000000-0000-4000-8000-000000000001');raise exception 'unexpected direct source RPC';exception when insufficient_privilege then null;end;end$$;
reset role;
select public.scenario_publish_with_review_sources('00000000-0000-4000-8000-000000000001','10000000-0000-4000-8000-000000000001','20000000-0000-4000-8000-000000000001',0,'40000000-0000-4000-8000-000000000002','public-project','50000000-0000-4000-8000-000000000001',repeat('b',64),'{"entities":[],"relations":[]}',repeat('c',64),null,'[]','{"public-project":{"entities":{},"relations":{}}}');
select public.fixture_assert((select count(*)=1 from scenario_private.review_sources),'publication stores private source atomically');
select public.fixture_assert(public.scenario_review_source('00000000-0000-4000-8000-000000000001','10000000-0000-4000-8000-000000000001','20000000-0000-4000-8000-000000000001','40000000-0000-4000-8000-000000000002')->>'projectionHash'=repeat('c',64),'verified author source receipt');
do $$begin begin perform public.scenario_review_source('00000000-0000-4000-8000-000000000003','10000000-0000-4000-8000-000000000003','20000000-0000-4000-8000-000000000001','40000000-0000-4000-8000-000000000002');raise exception 'unexpected reviewer source receipt';exception when insufficient_privilege then null;end;end$$;
do $$begin begin perform public.scenario_publish_with_review_sources('00000000-0000-4000-8000-000000000001','10000000-0000-4000-8000-000000000001','20000000-0000-4000-8000-000000000001',0,'40000000-0000-4000-8000-000000000003','public-project','50000000-0000-4000-8000-000000000001',repeat('b',64),'{}',repeat('d',64),null,'[]',null);raise exception 'unexpected null source';exception when raise_exception then if sqlerrm<>'PROTOCOL_INVALID'then raise;end if;end;end$$;
select public.fixture_assert(not exists(select 1 from public.scenario_snapshots where id='40000000-0000-4000-8000-000000000003'),'bad source publication changes nothing');
update public.scenario_snapshots set withdrawn_at=clock_timestamp()where id='40000000-0000-4000-8000-000000000002';
do $$begin begin perform public.scenario_review_source('00000000-0000-4000-8000-000000000001','10000000-0000-4000-8000-000000000001','20000000-0000-4000-8000-000000000001','40000000-0000-4000-8000-000000000002');raise exception 'unexpected withdrawn source';exception when insufficient_privilege then null;end;end$$;
update scenario_private.memberships set expires_at=clock_timestamp()+interval '20 milliseconds'where account_id='00000000-0000-4000-8000-000000000001';
select pg_sleep(.03);
set local role authenticated;
select public.fixture_assert((select count(*)=0 from public.scenario_comments),'elapsed membership stops same-transaction comments');
reset role;
rollback;
